const queries = [
  '"diagramação editorial" orçamento',
  '"projeto editorial" livro editora',
  '"relatório anual" diagramação',
  '"catálogo" diagramação design editorial',
  '"publicação" "projeto gráfico'',
  '"livro" "projeto gráfico" contratar'
];
return queries.map((query) => ({ json: { query } }));

const emailPattern = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
const blockedHosts = new Set(['google.com', 'facebook.com', 'instagram.com', 'linkedin.com', 'youtube.com', 'tiktok.com', 'x.com']);
const terms = ['diagramação', 'diagramacao', 'editorial', 'livro', 'catálogo', 'catalogo', 'relatório anual', 'relatorio anual', 'revista', 'publicação', 'publicacao', 'editora', 'projeto gráfico', 'projeto grafico', 'orçamento', 'orcamento', 'contratar', 'briefing'];
const results = [];
for (const item of $input.all()) {
  const source = item.json || {};
  const tavilyResults = Array.isArray(source.results) ? source.results : [];
  for (const result of tavilyResults) {
    const link = String(result.url || '').trim();
    let parsed;
    try { parsed = new URL(link); } catch { continue; }
    if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password) continue;
    const host = parsed.hostname.replace(/^www\./, '').toLowerCase();
    if (!host || blockedHosts.has(host) || [...blockedHosts].some((blocked) => host.endsWith('.' + blocked))) continue;
    const title = String(result.title || '').replace(/\s+/g, ' ').trim();
    const snippet = String(result.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    const evidence = [title, snippet].filter(Boolean).join(' — ').slice(0, 1000);
    const searchable = evidence.toLocaleLowerCase('pt-BR');
    const matchedTerms = terms.filter((term) => searchable.includes(term));
    const emails = [...new Set((evidence.match(emailPattern) || []).map((email) => email.toLowerCase()))];
    const commercialSignal = /(contratar|orçamento|orcamento|proposta|briefing|serviço|servico|prazo|escopo)/i.test(searchable);
    const score = Math.min(100, matchedTerms.length * 12 + (emails.length ? 20 : 0) + (commercialSignal ? 25 : 0));
    if (matchedTerms.length < 2 || !commercialSignal || score < 45) continue;
    const normalizedUrl = parsed.origin + parsed.pathname.replace(/\/$/, '');
    results.push({
      json: {
        prospect_key: (emails[0] || host).toLowerCase(),
        prospect_name: title || host,
        prospect_email: emails[0] || '',
        prospect_url: normalizedUrl,
        source_url: normalizedUrl,
        evidence,
        matched_terms: matchedTerms,
        relevance_score: score
      }
    });
  }
}
const unique = new Map();
for (const item of results) {
  const key = item.json.prospect_email || item.json.prospect_url || item.json.prospect_key;
  const previous = unique.get(key);
  if (!previous || item.json.relevance_score > previous.json.relevance_score) unique.set(key, item);
}
return [...unique.values()].sort((a, b) => b.json.relevance_score - a.json.relevance_score);

const TEST_MODE = true;
const MAX_DAILY_DRAFTS = 3;
const PORTFOLIO_URL = 'https://SEU-DOMINIO.example/portfolio';
const LANDING_PAGE_URL = 'https://SEU-DOMINIO.example/diagramacao-de-livros';
const SUPPRESSION_EMAILS = [];
const candidates = $items('Validar e qualificar oportunidades').map((item) => item.json);
const processed = $items('Buscar contatos processados hoje').map((item) => item.json);
const processedText = processed.map((item) => JSON.stringify(item).toLowerCase()).join('\n');
const suppression = new Set(SUPPRESSION_EMAILS.map((value) => String(value).trim().toLowerCase()).filter(Boolean));
const validReference = (value) => { try { const url = new URL(value); return ['http:', 'https:'].includes(url.protocol) && !url.username && !url.password && !url.hostname.includes('SEU-DOMINIO'); } catch { return false; } };
const validEmail = (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
const validPortfolio = validReference(PORTFOLIO_URL) ? PORTFOLIO_URL : '';
const validLanding = validReference(LANDING_PAGE_URL) ? LANDING_PAGE_URL : '';
let remaining = Math.max(0, MAX_DAILY_DRAFTS - processed.length);
const output = [];
for (const candidate of candidates) {
  if (remaining <= 0) break;
  const email = String(candidate.prospect_email || '').trim().toLowerCase();
  const key = String(candidate.prospect_key || '').trim().toLowerCase();
  const sourceUrl = String(candidate.source_url || '').trim().toLowerCase();
  const alreadyProcessed = Boolean((email && processedText.includes(email)) || (key && processedText.includes(key)) || (sourceUrl && processedText.includes(sourceUrl)));
  const suppressed = Boolean(email && suppression.has(email));
  const referencesValid = Boolean(validPortfolio && validLanding);
  if (!validEmail(email) || alreadyProcessed || suppressed || !referencesValid) continue;
  const recipient = String(candidate.prospect_name || 'equipe').replace(/[\r\n]+/g, ' ').slice(0, 120);
  const marker = `[PROSPECCAO-EDITORIAL:${email || key}]`;
  const subject = `${marker} Uma ideia para o projeto editorial de ${recipient}`;
  const body = [`Olá, ${recipient}!`, '', 'Encontrei uma referência pública que indica um possível projeto editorial e achei que meu trabalho poderia contribuir na próxima etapa.', '', `Evidência encontrada: ${candidate.evidence}`, `Fonte pública: ${candidate.source_url}`, '', 'Trabalho com direção de arte, projeto gráfico e diagramação editorial, com atenção à clareza, consistência visual e preparação dos arquivos finais.', `Portfólio: ${validPortfolio}`, `Landing page de diagramação editorial: ${validLanding}`, '', 'Se houver um briefing em andamento, posso avaliar o escopo e compartilhar uma proposta adequada. Caso não seja relevante, basta responder solicitando não contato.', '', 'Abraços,', 'Rayssa Martins'].join('\n');
  output.push({ json: { ...candidate, prospect_email: email, prospect_subject: subject, prospect_body: body, evidence_url: candidate.source_url, test_mode: TEST_MODE, action: 'draft' } });
  remaining -= 1;
}
return output;
